export default function Page() {
  const socials = site.socials.filter((s) => SOCIAL_ICONS[s.label]);

  return (
    <>
      <SiteNav />
      <main>
        <section className="section page-top intro">
          <div className="wrap intro-grid">
            <div className="intro-copy">
              <Reveal>
                <p className="kicker">{home.kicker}</p>
              </Reveal>
              <Reveal delay={60}>
                <Typewriter as="h1" className="intro-name" text={home.hero.name} dot />
              </Reveal>
              <Reveal delay={120}>
                <p className="intro-lede">{home.hero.lede}</p>
              </Reveal>
              {socials.length > 0 && (
                <Reveal delay={180}>
                  <ul className="intro-socials">
                    {socials.map((s) => (
                      <li key={s.label}>
                        <a href={s.url} target="_blank" rel="noopener noreferrer" aria-label={s.label}>
                          {SOCIAL_ICONS[s.label]}
                        </a>
                      </li>
                    ))}
                  </ul>
                </Reveal>
              )}
              <Reveal delay={240}>
                <ul className="stat-tiles">
                  {home.stats.map((s) => (
                    <li key={s.label} className="stat-tile">
                      <strong>{s.value}</strong>
                      <span>{s.label}</span>
                    </li>
                  ))}
                </ul>
              </Reveal>
            </div>

            <Reveal delay={120} className="intro-media">
              <div className="intro-photo">
                <Image
                  src={home.hero.portrait}
                  alt={home.hero.name}
                  fill
                  priority
                  sizes="(max-width: 900px) 100vw, 420px"
                />
              </div>
            </Reveal>
          </div>
        </section>

        <section className="section about" id="about">
          <div className="wrap">
            <Reveal>
              <Typewriter as="h2" className="section-title" text="About me" dot />
            </Reveal>
            {home.about.map((p, i) => (
              <Reveal key={i} delay={i * 60}>
                <p className="about-para">{p}</p>
              </Reveal>
            ))}
          </div>
        </section>

        <section className="section tech" id="tech">
          <div className="wrap">
            <Reveal>
              <Typewriter as="h2" className="section-title" text="Tech stack" dot />
            </Reveal>
            <Reveal delay={60}>
              <ul className="tech-grid">
                {techItems.map((t) => (
                  <li
                    key={t}
                    className="tech-tile"
                    style={{ "--brand": TECH_BRANDS[t] ?? "var(--accent)" } as CSSProperties}
                  >
                    <span className="tech-badge">{TECH_ICONS[t] ?? DEFAULT_TECH_ICON}</span>
                    <span className="tech-name">{t}</span>
                  </li>
                ))}
              </ul>
            </Reveal>
          </div>
        </section>
      </main>
      <ContactSection />
      <SiteFooter />
    </>
  );
}
